@SocialScience.Identifiability.equivalent_symm : ∀ {Θ X Y : Type} {predict : Θ → X → Y} {design : X → Prop} {θ φ : Θ},
  SocialScience.Identifiability.Equivalent predict design θ φ →
    SocialScience.Identifiability.Equivalent predict design φ θ

@SocialScience.Identifiability.equivalent_trans : ∀ {Θ X Y : Type} {predict : Θ → X → Y} {design : X → Prop}
  {θ φ ψ : Θ},
  SocialScience.Identifiability.Equivalent predict design θ φ →
    SocialScience.Identifiability.Equivalent predict design φ ψ →
      SocialScience.Identifiability.Equivalent predict design θ ψ

@SocialScience.Identifiability.restrict_design : ∀ {Θ X Y : Type} {predict : Θ → X → Y} {small large : X → Prop}
  {θ φ : Θ},
  (∀ (x : X), small x → large x) →
    SocialScience.Identifiability.Equivalent predict large θ φ →
      SocialScience.Identifiability.Equivalent predict small θ φ

@SocialScience.Identifiability.more_probes_preserve_identification : ∀ {Θ X Y : Type} {predict : Θ → X → Y}
  {small large : X → Prop},
  (∀ (x : X), small x → large x) →
    SocialScience.Identifiability.Identified predict small → SocialScience.Identifiability.Identified predict large

@SocialScience.Identifiability.postprocess_preserves_equivalence : ∀ {Θ X Y Z : Type} {predict : Θ → X → Y}
  {design : X → Prop} {θ φ : Θ} (transform : Y → Z),
  SocialScience.Identifiability.Equivalent predict design θ φ →
    SocialScience.Identifiability.Equivalent (fun p x => transform (predict p x)) design θ φ

@SocialScience.Learning.fits_cons_iff : ∀ {X Y : Type} (hypothesis : X → Y) (x : X) (y : Y) (evidence : List (X × Y)),
  SocialScience.Learning.Fits hypothesis ((x, y) :: evidence) ↔
    hypothesis x = y ∧ SocialScience.Learning.Fits hypothesis evidence

@SocialScience.Learning.fits_append_iff : ∀ {X Y : Type} (hypothesis : X → Y) (first second : List (X × Y)),
  SocialScience.Learning.Fits hypothesis (first ++ second) ↔
    SocialScience.Learning.Fits hypothesis first ∧ SocialScience.Learning.Fits hypothesis second

@SocialScience.Learning.more_evidence_narrows_models : ∀ {X Y : Type} (hypothesis : X → Y) {small large : List (X × Y)},
  (∀ (item : X × Y), item ∈ small → item ∈ large) →
    SocialScience.Learning.Fits hypothesis large → SocialScience.Learning.Fits hypothesis small

@SocialScience.CollectiveAction.adding_members_preserves_feasibility : ∀ {Agent Task : Type}
  {canDo : Agent → Task → Prop} {small large : Agent → Prop},
  (∀ (agent : Agent), small agent → large agent) →
    SocialScience.CollectiveAction.Feasible canDo small → SocialScience.CollectiveAction.Feasible canDo large

@SocialScience.CollectiveAction.restricting_members_preserves_acceptance : ∀ {Agent : Type} {cost reward : Agent → Int}
  {small large : Agent → Prop},
  (∀ (agent : Agent), small agent → large agent) →
    SocialScience.CollectiveAction.Accepts cost reward large → SocialScience.CollectiveAction.Accepts cost reward small

@SocialScience.Aggregation.recoding_cannot_restore_components : ∀ {Y : Type} (recode : Int → Y),
  SocialScience.Identifiability.Equivalent (fun p probe => recode (SocialScience.Identifiability.twoComponent p probe))
    (fun probe => probe = false) (1, 0) (0, 1)
